{"proposals":[
  {
    "technique_id":"T1583.001",
    "template_id":"record-controlled-domain",
    "bindings":{"actor":"actor.primary","manifest":"infrastructure.lab_manifest"},
    "rationale":"Stage a lab‑only domain manifest to re‑register expired C2 domains in a controlled environment, matching the campaign’s resource‑development activity.",
    "source":"llm"
  },
  {
    "technique_id":"T1005",
    "template_id":"collect-declared-data-fixture",
    "bindings":{"data_source":"data.synthetic_fixture","target":"target.primary"},
    "rationale":"Collect synthetic documents from the target host, mirroring the campaign’s data‑collection from compromised hosts while using a benign data source.",
    "source":"llm"
  },
  {
    "technique_id":"T1560.001",
    "template_id":"archive-declared-collection",
    "bindings":{"archive_tool":"archive_tool.local","target":"target.primary"},
    "rationale":"Archive the collected synthetic data with a local utility, aligning with the campaign’s use of a utility to bundle stolen files.",
    "source":"llm"
  },
  {
    "technique_id":"T1105",
    "template_id":"transfer-benign-payload",
    "bindings":{"channel":"channel.private_http","payload":"payload.benign","target":"target.primary"},
    "rationale":"Transfer a staged benign payload over a private lab channel, reflecting the campaign’s tool transfer via a private channel.",
    "source":"llm"
  },
  {
    "technique_id":"T1568",
    "template_id":"resolve-lab-domain",
    "bindings":{"domain":"infrastructure.lab_manifest","target":"target.primary"},
    "rationale":"Resolve the lab‑only domain through the controlled resolver, matching the dynamic DNS resolution step in the campaign.",
    "source":"llm"
  },
  {
    "technique_id":"T1030",
    "template_id":"split-declared-archive",
    "bindings":{"archive":"archive.synthetic_collection","chunk_policy":"chunk_policy.bounded_local"},
    "rationale":"Split the synthetic archive into bounded chunks, emulating the campaign’s 3 MB part splitting before exfiltration.",
    "source":"llm"
  }
]}
